626:   function draw() {
627:     ctx.save();
628:     if (state.shake > 0) {
629:       ctx.translate(rand(-state.shake, state.shake), rand(-state.shake, state.shake));
630:     }
631:     drawBackground();
632:     snacks.forEach(drawSnack);
633:     const actors = [...enemies.map((enemy) => ({ obj: enemy, player: false })), { obj: player, player: true }].sort((a, b) => a.obj.y - b.obj.y);
634:     actors.forEach(({ obj, player: isPlayer }) => drawCharacter(obj, isPlayer));
635:     drawParticles();
636:     ctx.restore();
637:   }
