639:   function update(dt) {
640:     state.anim += dt;
641:     if (state.toastTimer > 0) {
642:       state.toastTimer -= dt;
643:       if (state.toastTimer <= 0) {
644:         toast.classList.remove('show');
645:       }
646:     }
647:     state.shake = Math.max(0, state.shake - dt * 10);
648:     state.time -= dt;
649:     if (state.time <= 0) {
650:       state.time = 0;
651:       finishGame(state.defeats >= state.total);
652:       return;
653:     }
654: 
655:     let playerMoveX = 0;
656:     let playerMoveY = 0;
657:     if (keys.has('d') || keys.has('arrowright')) playerMoveX += 1;
658:     if (keys.has('a') || keys.has('arrowleft')) playerMoveX -= 1;
659:     if (keys.has('s') || keys.has('arrowdown')) playerMoveY += 1;
660:     if (keys.has('w') || keys.has('arrowup')) playerMoveY -= 1;
661: 
662:     if (player.dash > 0) {
663:       player.vx = player.dashX * 520;
664:       player.vy = player.dashY * 520;
665:     } else if (playerMoveX || playerMoveY) {
666:       const length = Math.hypot(playerMoveX, playerMoveY) || 1;
667:       player.vx = (playerMoveX / length) * player.speed;
668:       player.vy = (playerMoveY / length) * player.speed;
669:       if (playerMoveX !== 0) player.face = playerMoveX > 0 ? 1 : -1;
670:     } else {
671:       player.vx *= 0.7;
672:       player.vy *= 0.7;
673:     }
674: 
675:     if (player.attack > 0) player.attack = Math.max(0, player.attack - dt);
676:     if (player.dash > 0) player.dash = Math.max(0, player.dash - dt);
677:     if (player.dashLock > 0) player.dashLock -= dt;
678:     if (player.invuln > 0) player.invuln -= dt;
679: 
680:     player.x = clamp(player.x + player.vx * dt, 50, W - 50);
681:     player.y = clamp(player.y + player.vy * dt, 330, 485);
682: 
683:     state.spawnWait -= dt;
684:     if (state.spawnWait <= 0 && enemies.length < state.total - state.defeats) {
685:       spawnEnemy();
686:       state.spawnWait = rand(1.3, 2.4);
687:     }
688: 
689:     enemies.forEach((enemy) => {
690:       enemy.flash = Math.max(0, enemy.flash - dt);
691:       enemy.attack = Math.max(0, enemy.attack - dt);
692:       enemy.anim += dt;
693:       const dx = player.x - enemy.x;
694:       const dy = player.y - enemy.y;
695:       const dist = Math.hypot(dx, dy) || 1;
696:       const targetSpeed = enemy.speed * (enemy.type === 'runner' ? 1.15 : 1);
697: 
698:       if (dist > 40) {
699:         enemy.mode = 'chase';
700:         const nx = dx / dist;
701:         const ny = dy / dist;
702:         enemy.x += nx * targetSpeed * dt;
703:         enemy.y += ny * targetSpeed * dt;
704:       } else {
705:         enemy.mode = 'idle';
706:       }
707: 
708:       if (dist < 42) {
709:         enemy.face = dx > 0 ? 1 : -1;
710:         if (enemy.cool <= 0) {
711:           enemy.cool = rand(0.8, 1.4);
712:           enemy.attack = 0.18;
713:           if (player.invuln <= 0) {
714:             player.hp -= enemy.type === 'brute' ? 16 : 11;
715:             player.invuln = 0.6;
716:             state.shake = 7;
717:             sound(120, 0.09, 'sawtooth', 0.03);
718:           }
719:         }
720:       }
721: 
722:       enemy.cool -= dt;
723:       enemy.x = clamp(enemy.x, 46, W - 46);
724:       enemy.y = clamp(enemy.y, 330, 485);
725:     });
726: 
727:     snacks = snacks.filter((snack) => {
728:       const dx = snack.x - player.x;
729:       const dy = snack.y - player.y;
730:       const dist = Math.hypot(dx, dy);
731:       if (dist < 26) {
732:         player.hp = clamp(player.hp + 18, 0, player.maxHp);
733:         state.score += 150;
734:         setToast('TORTA ENERGY!');
735:         sound(660, 0.09, 'triangle', 0.03);
736:         return false;
737:       }
738:       snack.age += dt;
739:       return snack.age < 8;
740:     });
741: 
742:     particles.forEach((particle) => {
743:       particle.x += particle.vx * dt;
744:       particle.y += particle.vy * dt;
745:       particle.life -= dt;
746:       particle.vy += 100 * dt;
747:     });
748:     particles = particles.filter((particle) => particle.life > 0);
749: 
750:     if (player.hp <= 0) {
751:       player.hp = 0;
752:       finishGame(false);
753:       return;
754:     }
755: 
756:     if (state.defeats >= state.total) {
757:       finishGame(true);
758:       return;
759:     }
760: 
761:     updateHud();
762:   }
