764:   function frame(timestamp) {
765:     if (!state.last) state.last = timestamp;
766:     const dt = Math.min((timestamp - state.last) / 1000, 0.033);
767:     state.last = timestamp;
768:     if (state.mode === 'playing') {
769:       update(dt);
770:     } else {
771:       state.anim += dt;
772:       if (state.toastTimer > 0) {
773:         state.toastTimer -= dt;
774:         if (state.toastTimer <= 0) toast.classList.remove('show');
775:       }
776:     }
777:     draw();
778:     requestAnimationFrame(frame);
779:   }
