781:   function keyForEvent(event) {
782:     const key = event.key.toLowerCase();
783:     return key;
784:   }
785: 
786:   document.addEventListener('keydown', (event) => {
787:     const key = keyForEvent(event);
788:     if (['w', 'a', 's', 'd', 'arrowup', 'arrowdown', 'arrowleft', 'arrowright', ' '].includes(key) || event.code === 'Space') {
789:       event.preventDefault();
790:     }
791:     if (event.repeat && (key === 'enter' || key === 'escape' || event.code === 'Space' || key === 'shift')) return;
792:     if (key === 'enter' && (state.mode === 'intro' || state.mode === 'won' || state.mode === 'lost')) {
793:       startGame();
794:       return;
795:     }
796:     if (event.key === 'Escape') {
797:       pauseGame();
798:       return;
799:     }
800:     if (event.code === 'Space' && state.mode === 'playing') {
801:       punch();
802:       return;
803:     }
804:     if (event.key === 'Shift' && state.mode === 'playing') {
805:       dash();
806:       return;
807:     }
808:     keys.add(key);
809:     touchKeys.add(key);
810:   });
811: 
812:   document.addEventListener('keyup', (event) => {
813:     const key = keyForEvent(event);
814:     keys.delete(key);
815:     touchKeys.delete(key);
816:   });
